package org.ruralnet.api;

import org.ruralnet.graph.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.util.*;

@RestController @RequestMapping("/api/v1")
public class ApiController {
  private final JdbcTemplate db;
  private final ObjectMapper json;
  public ApiController(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
  private Map<String,Object> ok(Object data){return Map.of("data",data,"meta",Map.of("requestId",UUID.randomUUID().toString()));}
  private static UUID uuid(String s){try{return UUID.fromString(s);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid UUID");}}
  private GraphSnapshot load(Set<UUID> disabled){
    var ns=db.query("SELECT BIN_TO_UUID(id) id,code,name,type,latitude,longitude FROM infrastructure_nodes ORDER BY code",(r,i)->new GraphSnapshot.Node(UUID.fromString(r.getString("id")),r.getString("code"),r.getString("name"),r.getString("type"),r.getDouble("latitude"),r.getDouble("longitude")));
    var es=db.query("SELECT BIN_TO_UUID(id) id,BIN_TO_UUID(node_a_id) a,BIN_TO_UUID(node_b_id) b,distance_km,construction_cost,capacity,status FROM infrastructure_edges",(r,i)->new GraphSnapshot.Edge(UUID.fromString(r.getString("id")),UUID.fromString(r.getString("a")),UUID.fromString(r.getString("b")),r.getBigDecimal("distance_km"),r.getBigDecimal("construction_cost"),r.getBigDecimal("capacity"),disabled.contains(UUID.fromString(r.getString("id")))?"DISABLED":r.getString("status")));
    long rev=db.queryForObject("SELECT COALESCE(MAX(revision_number),0) FROM network_revisions",Long.class);return new GraphSnapshot(ns,es,rev);
  }
  private void revision(String reason){UUID id=UUID.randomUUID();db.update("INSERT INTO network_revisions(id,reason) VALUES(UUID_TO_BIN(?),?)",id.toString(),reason);db.update("INSERT INTO network_revision_nodes SELECT UUID_TO_BIN(?),id,code,name,type,latitude,longitude,demand,supply,description FROM infrastructure_nodes",id.toString());db.update("INSERT INTO network_revision_edges SELECT UUID_TO_BIN(?),id,node_a_id,node_b_id,distance_km,construction_cost,capacity,status FROM infrastructure_edges",id.toString());}
  private Set<UUID> simulationIds(String id){return id==null?Set.of():disabled(uuid(id).toString());}
  private GraphSnapshot loadSnapshot(String id){UUID rid=UUID.fromString(db.queryForObject("SELECT BIN_TO_UUID(id) FROM network_revisions WHERE revision_number=(SELECT revision_number FROM active_simulations WHERE id=UUID_TO_BIN(?))",String.class,id));long rev=db.queryForObject("SELECT revision_number FROM active_simulations WHERE id=UUID_TO_BIN(?)",Long.class,id);var ns=db.query("SELECT BIN_TO_UUID(id) id,code,name,type,latitude,longitude FROM network_revision_nodes WHERE revision_id=UUID_TO_BIN(?) ORDER BY code",(r,i)->new GraphSnapshot.Node(UUID.fromString(r.getString("id")),r.getString("code"),r.getString("name"),r.getString("type"),r.getDouble("latitude"),r.getDouble("longitude")),rid.toString());var es=db.query("SELECT BIN_TO_UUID(id) id,BIN_TO_UUID(node_a_id) a,BIN_TO_UUID(node_b_id) b,distance_km,construction_cost,capacity,status FROM network_revision_edges WHERE revision_id=UUID_TO_BIN(?)",(r,i)->new GraphSnapshot.Edge(UUID.fromString(r.getString("id")),UUID.fromString(r.getString("a")),UUID.fromString(r.getString("b")),r.getBigDecimal("distance_km"),r.getBigDecimal("construction_cost"),r.getBigDecimal("capacity"),r.getString("status")),rid.toString());return new GraphSnapshot(ns,es,rev);}
  private GraphSnapshot loadContext(String simulationId){return simulationId==null?load(Set.of()):baseWithFailures(uuid(simulationId).toString());}
  @GetMapping("/network") public Map<String,Object> network(@RequestParam(required=false) String simulationId){var g=loadContext(simulationId);var f=GraphAlgorithms.kruskal(g);return ok(Map.of("revision",g.revision(),"nodes",g.nodes(),"edges",g.edges(),"components",f.components(),"warnings",List.of()));}
  @PostMapping("/network/validate") public Map<String,Object> validateNetwork(@RequestBody(required=false) Map<String,String> in){var g=loadContext(in==null?null:in.get("simulationId"));Set<UUID> ids=new HashSet<>();g.nodes().forEach(n->ids.add(n.id()));List<String>warnings=new ArrayList<>();for(var e:g.edges()){if(!ids.contains(e.a())||!ids.contains(e.b()))warnings.add("Connection "+e.id()+" refers to a missing location.");if(e.a().equals(e.b()))warnings.add("Connection "+e.id()+" is a self-loop.");}var f=GraphAlgorithms.kruskal(g);return ok(Map.of("valid",warnings.isEmpty(),"nodeCount",g.nodes().size(),"edgeCount",g.edges().size(),"activeEdgeCount",g.activeEdges().size(),"componentCount",f.components(),"warnings",warnings,"revision",g.revision()));}
  @GetMapping("/nodes") public Map<String,Object> nodes(){return ok(load(Set.of()).nodes());}
  @GetMapping("/edges") public Map<String,Object> edges(){return ok(load(Set.of()).edges());}
  @GetMapping("/nodes/{id}") public Map<String,Object> node(@PathVariable String id){var rows=db.query("SELECT BIN_TO_UUID(id) id,code,name,type,latitude,longitude,demand,supply,description,version FROM infrastructure_nodes WHERE id=UUID_TO_BIN(?)",(r,i)->Map.of("id",r.getString("id"),"code",r.getString("code"),"name",r.getString("name"),"type",r.getString("type"),"latitude",r.getBigDecimal("latitude"),"longitude",r.getBigDecimal("longitude"),"demand",r.getBigDecimal("demand"),"supply",r.getBigDecimal("supply"),"description",Objects.toString(r.getString("description"),""),"version",r.getLong("version")),uuid(id).toString());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Location not found");return ok(rows.getFirst());}
  @PatchMapping("/nodes/{id}") @Transactional public Map<String,Object> patchNode(@PathVariable String id,@RequestBody Map<String,Object> x){if(!x.containsKey("version"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Version is required");long v=((Number)x.get("version")).longValue();try{int c=db.update("UPDATE infrastructure_nodes SET name=COALESCE(?,name),type=COALESCE(?,type),latitude=COALESCE(?,latitude),longitude=COALESCE(?,longitude),demand=COALESCE(?,demand),supply=COALESCE(?,supply),description=COALESCE(?,description),version=version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE id=UUID_TO_BIN(?) AND version=?",x.get("name"),x.get("type"),x.get("latitude"),x.get("longitude"),x.get("demand"),x.get("supply"),x.get("description"),uuid(id).toString(),v);if(c==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Location version is stale or the location no longer exists");revision("Update location");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Location fields are invalid");}return node(id);}
  @DeleteMapping("/nodes/{id}") @Transactional public ResponseEntity<?> deleteNode(@PathVariable String id,@RequestParam(defaultValue="false") boolean cascade){if(db.queryForObject("SELECT COUNT(*) FROM infrastructure_nodes WHERE id=UUID_TO_BIN(?)",Integer.class,uuid(id).toString())==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Location not found");int edges=db.queryForObject("SELECT COUNT(*) FROM infrastructure_edges WHERE node_a_id=UUID_TO_BIN(?) OR node_b_id=UUID_TO_BIN(?)",Integer.class,id,id);if(edges>0&&!cascade)throw new ResponseStatusException(HttpStatus.CONFLICT,"Location has connections. Confirm cascade=true to remove it and its links.");db.update("DELETE FROM infrastructure_nodes WHERE id=UUID_TO_BIN(?)",id);revision("Delete location");return ResponseEntity.noContent().build();}
  public record NodeIn(@NotBlank @Size(max=40) String code,@NotBlank @Size(max=160) String name,@NotBlank String type,@DecimalMin("-90") @DecimalMax("90") double latitude,@DecimalMin("-180") @DecimalMax("180") double longitude,@DecimalMin("0") BigDecimal demand,@DecimalMin("0") BigDecimal supply,String description){}
  public record EdgeIn(@NotNull UUID nodeAId,@NotNull UUID nodeBId,@DecimalMin(value="0.001") BigDecimal distanceKm,@DecimalMin("0") BigDecimal constructionCost,@DecimalMin("0") BigDecimal capacity,String status){}
  @PostMapping("/nodes") @Transactional public ResponseEntity<?> createNode(@Valid @RequestBody NodeIn x){if(!Set.of("VILLAGE","HOSPITAL","SCHOOL","WAREHOUSE","WATER_FACILITY","POWER_STATION","DISTRIBUTION_CENTER").contains(x.type()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Location type is invalid");UUID id=UUID.randomUUID();try{db.update("INSERT INTO infrastructure_nodes(id,code,name,type,latitude,longitude,demand,supply,description) VALUES(UUID_TO_BIN(?),?,?,?,?,?,?,?,?)",id.toString(),x.code(),x.name(),x.type(),x.latitude(),x.longitude(),x.demand()==null?BigDecimal.ZERO:x.demand(),x.supply()==null?BigDecimal.ZERO:x.supply(),x.description());revision("Create node "+x.code());}catch(Exception e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Node code must be unique");}return ResponseEntity.status(201).body(ok(Map.of("id",id,"code",x.code())));}
  @PostMapping("/edges") @Transactional public ResponseEntity<?> createEdge(@Valid @RequestBody EdgeIn x){if(x.nodeAId().equals(x.nodeBId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Select two different locations");if(!Set.of("ACTIVE","DISABLED","PLANNED").contains(x.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid connection status");UUID id=UUID.randomUUID(),lo=x.nodeAId().compareTo(x.nodeBId())<0?x.nodeAId():x.nodeBId(),hi=lo.equals(x.nodeAId())?x.nodeBId():x.nodeAId();try{db.update("INSERT INTO infrastructure_edges(id,node_a_id,node_b_id,endpoint_low_id,endpoint_high_id,distance_km,construction_cost,capacity,status) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,?,?,?,?)",id.toString(),x.nodeAId().toString(),x.nodeBId().toString(),lo.toString(),hi.toString(),x.distanceKm(),x.constructionCost(),x.capacity()==null?BigDecimal.ZERO:x.capacity(),x.status());revision("Create edge");}catch(Exception e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Connection pair must be unique and both locations must exist");}return ResponseEntity.status(201).body(ok(Map.of("id",id)));}
  @DeleteMapping("/edges/{id}") @Transactional public ResponseEntity<?> deleteEdge(@PathVariable String id){int removed=db.update("DELETE FROM infrastructure_edges WHERE id=UUID_TO_BIN(?)",uuid(id).toString());if(removed==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Connection not found");revision("Delete edge");return ResponseEntity.noContent().build();}
  @GetMapping("/edges/{id}") public Map<String,Object> edge(@PathVariable String id){var g=load(Set.of());var e=g.edges().stream().filter(x->x.id().equals(uuid(id))).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Connection not found"));return ok(e);}
  @PatchMapping("/edges/{id}") @Transactional public Map<String,Object> patchEdge(@PathVariable String id,@RequestBody Map<String,Object> x){if(!x.containsKey("version"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Version is required");int count=db.update("UPDATE infrastructure_edges SET distance_km=COALESCE(?,distance_km),construction_cost=COALESCE(?,construction_cost),capacity=COALESCE(?,capacity),status=COALESCE(?,status),version=version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE id=UUID_TO_BIN(?) AND version=?",x.get("distanceKm"),x.get("constructionCost"),x.get("capacity"),x.get("status"),uuid(id).toString(),((Number)x.get("version")).longValue());if(count==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Connection version is stale or the connection no longer exists");revision("Update connection");return edge(id);}
  @PostMapping("/optimizations") @Transactional public ResponseEntity<?> optimize(@RequestBody Map<String,String> in){String alg=in.getOrDefault("algorithm","KRUSKAL");if(!Set.of("KRUSKAL","PRIM").contains(alg))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Algorithm must be KRUSKAL or PRIM");if(!in.getOrDefault("metric","COST").equals("COST"))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"MST supports COST only in release 1");var g=loadContext(in.get("simulationId"));if(g.nodes().isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Add locations before optimizing");var result=alg.equals("PRIM")?GraphAlgorithms.prim(g):GraphAlgorithms.kruskal(g);var payload=Map.of("algorithm",alg,"metric","COST","revision",g.revision(),"edgeIds",result.edges().stream().map(e->e.id().toString()).toList(),"edges",result.edges(),"totalCost",result.totalCost(),"componentCount",result.components(),"componentCosts",result.componentCosts(),"isolatedNodeIds",result.isolatedNodeIds(),"executionTimeMs",result.executionTimeMs());if("true".equalsIgnoreCase(in.get("save"))){if(in.get("simulationId")!=null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Only baseline optimization runs can be saved in this release");try{UUID id=UUID.randomUUID();String revId=db.queryForObject("SELECT BIN_TO_UUID(id) FROM network_revisions WHERE revision_number=?",String.class,g.revision());db.update("INSERT INTO optimization_runs(id,revision_id,algorithm,metric,selected_edges_json,result_json,name,notes,result_schema_version) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),?,?,CAST(? AS JSON),CAST(? AS JSON),?,?,1)",id.toString(),revId,alg,"COST",json.writeValueAsString(payload.get("edgeIds")),json.writeValueAsString(payload),in.get("name"),in.get("notes"));}catch(Exception e){throw new IllegalStateException(e);}}return ResponseEntity.ok(ok(payload));}
  @PostMapping("/routes/shortest-path") public Map<String,Object> route(@RequestBody Map<String,String> in){var g=loadContext(in.get("simulationId"));String metric=in.get("metric");if(!Set.of("COST","DISTANCE").contains(metric))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Metric must be COST or DISTANCE");UUID source=uuid(in.get("sourceNodeId")),destination=uuid(in.get("destinationNodeId"));if(source.equals(destination))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Choose two different locations");if(g.nodes().stream().noneMatch(n->n.id().equals(source))||g.nodes().stream().noneMatch(n->n.id().equals(destination)))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Route endpoint does not exist in this network revision");return ok(GraphAlgorithms.dijkstra(g,source,destination,metric));}
  @GetMapping("/resilience/criticality") public Map<String,Object> criticality(@RequestParam(required=false) String simulationId){var g=load(simulationIds(simulationId));var c=GraphAlgorithms.criticality(g);return ok(Map.of("bridgeEdgeIds",c.bridgeEdgeIds(),"articulationNodeIds",c.articulationNodeIds()));}
  @PostMapping("/sample-data/initialize") @Transactional public ResponseEntity<?> sample(){if(db.queryForObject("SELECT COUNT(*) FROM infrastructure_nodes WHERE sample_data=true",Integer.class)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Demonstration network is already initialized");String[] types={"VILLAGE","VILLAGE","VILLAGE","VILLAGE","VILLAGE","HOSPITAL","HOSPITAL","SCHOOL","SCHOOL","WATER_FACILITY","WATER_FACILITY","POWER_STATION","WAREHOUSE","DISTRIBUTION_CENTER"};String[] names={"Asha Village","Bela Village","Chandpur Village","Devgarh Village","Ektara Village","North Clinic","River Hospital","Central School","East School","Hill Water Works","River Pump","Grid Station","Farm Warehouse","District Hub"};UUID[] ids=new UUID[14];for(int i=0;i<14;i++){ids[i]=UUID.randomUUID();db.update("INSERT INTO infrastructure_nodes(id,code,name,type,latitude,longitude,demand,supply,sample_data) VALUES(UUID_TO_BIN(?),?,?,?,?,?,?,?,true)",ids[i].toString(),String.format("%s-%03d",types[i].substring(0,3),i+1),names[i],types[i],18.45+i*.012,73.72+i*.014,BigDecimal.valueOf(40+i*3),BigDecimal.valueOf(i==11?500:0));}
    int[][] pairs={{0,1},{1,2},{2,3},{3,4},{4,0},{0,5},{2,6},{1,7},{4,9},{5,10},{6,11},{7,12},{8,13},{10,11},{6,10}};for(int i=0;i<pairs.length;i++){int a=pairs[i][0],b=pairs[i][1];UUID id=UUID.randomUUID(),lo=ids[a].compareTo(ids[b])<0?ids[a]:ids[b],hi=lo.equals(ids[a])?ids[b]:ids[a];BigDecimal cost=BigDecimal.valueOf(i<5?10000:15000+i*1700);db.update("INSERT INTO infrastructure_edges(id,node_a_id,node_b_id,endpoint_low_id,endpoint_high_id,distance_km,construction_cost,capacity,status,sample_data) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,?,?,?,true)",id.toString(),ids[a].toString(),ids[b].toString(),lo.toString(),hi.toString(),BigDecimal.valueOf(4+i*1.35),cost,BigDecimal.valueOf(70+i*5),i>=13?"PLANNED":"ACTIVE");}revision("Initialize demonstration network");return ResponseEntity.status(201).body(ok(Map.of("nodes",14,"edges",pairs.length,"synthetic",true)));}
  @PostMapping("/sample-data/reset") @Transactional public Map<String,Object> resetSample(@RequestBody Map<String,String> in){if(!"RESET_SAMPLE_DATA".equals(in.get("confirmation")))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Enter RESET_SAMPLE_DATA to confirm");int attached=db.queryForObject("SELECT COUNT(*) FROM infrastructure_edges e JOIN infrastructure_nodes a ON a.id=e.node_a_id JOIN infrastructure_nodes b ON b.id=e.node_b_id WHERE e.sample_data=false AND (a.sample_data=true OR b.sample_data=true)",Integer.class);if(attached>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Sample locations are connected to operational links. Remove those links before resetting sample data.");int edges=db.update("DELETE FROM infrastructure_edges WHERE sample_data=true");int nodes=db.update("DELETE FROM infrastructure_nodes WHERE sample_data=true");revision("Reset demonstration network");return ok(Map.of("removedNodes",nodes,"removedEdges",edges));}
  @GetMapping("/dashboard") public Map<String,Object> dashboard(@RequestParam(required=false) String simulationId){var g=loadContext(simulationId);var f=GraphAlgorithms.kruskal(g);var c=GraphAlgorithms.criticality(g);Map<String,Long> types=new TreeMap<>();g.nodes().forEach(n->types.merge(n.type(),1L,Long::sum));BigDecimal active=g.activeEdges().stream().map(GraphSnapshot.Edge::cost).reduce(BigDecimal.ZERO,BigDecimal::add);return ok(Map.of("nodeCount",g.nodes().size(),"activeEdgeCount",g.activeEdges().size(),"totalActiveEdgeCost",active,"forestCost",f.totalCost(),"componentCount",f.components(),"isolatedNodeIds",f.isolatedNodeIds(),"bridgeCount",c.bridgeEdgeIds().size(),"nodeTypes",types,"revision",g.revision()));}
  @GetMapping("/history/optimizations") public Map<String,Object> optimizationHistory(){var rows=db.query("SELECT BIN_TO_UUID(id) id,algorithm,metric,name,notes,created_at,CAST(result_json AS CHAR) result FROM optimization_runs ORDER BY created_at DESC",(r,i)->{try{return Map.of("id",r.getString("id"),"algorithm",r.getString("algorithm"),"metric",r.getString("metric"),"name",Objects.toString(r.getString("name"),""),"notes",Objects.toString(r.getString("notes"),""),"createdAt",r.getTimestamp("created_at").toInstant().toString(),"result",json.readTree(r.getString("result")));}catch(Exception e){throw new IllegalStateException(e);}});return ok(rows);}
  private Set<UUID> disabled(String id){String raw=db.queryForObject("SELECT CAST(disabled_edge_ids_json AS CHAR) FROM active_simulations WHERE id=UUID_TO_BIN(?)",String.class,id);try{return new HashSet<>(json.readValue(raw,new TypeReference<List<UUID>>(){}));}catch(Exception e){throw new IllegalStateException("Invalid simulation snapshot",e);}}
  private Map<String,Object> scenario(String id){long rev=db.queryForObject("SELECT revision_number FROM active_simulations WHERE id=UUID_TO_BIN(?)",Long.class,id);Set<UUID> off=disabled(id);var base=loadSnapshot(id);var simulated=baseWithFailures(id);var bf=GraphAlgorithms.kruskal(base);var sf=GraphAlgorithms.kruskal(simulated);var c=GraphAlgorithms.criticality(simulated);Set<UUID> impacted=new TreeSet<>();if(sf.components()>bf.components())for(var n:base.nodes())if(!componentKey(base,n.id()).equals(componentKey(simulated,n.id())))impacted.add(n.id());return Map.ofEntries(Map.entry("id",id),Map.entry("baselineRevision",rev),Map.entry("version",db.queryForObject("SELECT version FROM active_simulations WHERE id=UUID_TO_BIN(?)",Long.class,id)),Map.entry("disabledEdgeIds",off),Map.entry("componentCount",sf.components()),Map.entry("baselineComponentCount",bf.components()),Map.entry("affectedNodeIds",impacted),Map.entry("baselineForestCost",bf.totalCost()),Map.entry("failedForestCost",sf.totalCost()),Map.entry("extraConnectionCost",sf.components()==bf.components()?sf.totalCost().subtract(bf.totalCost()):BigDecimal.ZERO),Map.entry("bridgeEdgeIds",c.bridgeEdgeIds()),Map.entry("articulationNodeIds",c.articulationNodeIds()),Map.entry("nodeCount",simulated.nodes().size()),Map.entry("activeEdgeCount",simulated.activeEdges().size()));}
  private GraphSnapshot baseWithFailures(String id){UUID rid=UUID.fromString(db.queryForObject("SELECT BIN_TO_UUID(id) FROM network_revisions WHERE revision_number=(SELECT revision_number FROM active_simulations WHERE id=UUID_TO_BIN(?))",String.class,id));long rev=db.queryForObject("SELECT revision_number FROM active_simulations WHERE id=UUID_TO_BIN(?)",Long.class,id);var ns=db.query("SELECT BIN_TO_UUID(id) id,code,name,type,latitude,longitude FROM network_revision_nodes WHERE revision_id=UUID_TO_BIN(?) ORDER BY code",(r,i)->new GraphSnapshot.Node(UUID.fromString(r.getString("id")),r.getString("code"),r.getString("name"),r.getString("type"),r.getDouble("latitude"),r.getDouble("longitude")),rid.toString());Set<UUID> off=disabled(id);var es=db.query("SELECT BIN_TO_UUID(id) id,BIN_TO_UUID(node_a_id) a,BIN_TO_UUID(node_b_id) b,distance_km,construction_cost,capacity,status FROM network_revision_edges WHERE revision_id=UUID_TO_BIN(?)",(r,i)->new GraphSnapshot.Edge(UUID.fromString(r.getString("id")),UUID.fromString(r.getString("a")),UUID.fromString(r.getString("b")),r.getBigDecimal("distance_km"),r.getBigDecimal("construction_cost"),r.getBigDecimal("capacity"),off.contains(UUID.fromString(r.getString("id")))?"DISABLED":r.getString("status")),rid.toString());return new GraphSnapshot(ns,es,rev);}
  private String componentKey(GraphSnapshot g,UUID start){Map<UUID,List<UUID>> a=new HashMap<>();for(var e:g.activeEdges()){a.computeIfAbsent(e.a(),k->new ArrayList<>()).add(e.b());a.computeIfAbsent(e.b(),k->new ArrayList<>()).add(e.a());}Set<UUID>s=new TreeSet<>();Deque<UUID>q=new ArrayDeque<>();q.add(start);while(!q.isEmpty()){UUID x=q.remove();if(s.add(x))q.addAll(a.getOrDefault(x,List.of()));}return s.toString();}
  @PostMapping("/simulations") @Transactional public ResponseEntity<?> createScenario(@RequestBody Map<String,Object> in){Set<UUID> off=parseIds(in.get("disabledEdgeIds"));var current=load(Set.of());Set<UUID> known=new HashSet<>();current.edges().forEach(e->known.add(e.id()));if(!known.containsAll(off))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"One or more connection IDs do not exist");UUID id=UUID.randomUUID();try{db.update("INSERT INTO active_simulations(id,revision_number,disabled_edge_ids_json,name) VALUES(UUID_TO_BIN(?),?,?,?)",id.toString(),current.revision(),json.writeValueAsString(off),in.get("name"));}catch(Exception e){throw new IllegalStateException(e);}return ResponseEntity.status(201).body(ok(scenario(id.toString())));}
  private Set<UUID> parseIds(Object raw){if(raw==null)return new HashSet<>();if(!(raw instanceof Collection<?> c))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"disabledEdgeIds must be a list");Set<UUID> out=new HashSet<>();for(Object x:c)out.add(uuid(String.valueOf(x)));return out;}
  @PatchMapping("/simulations/{id}") @Transactional public Map<String,Object> updateScenario(@PathVariable String id,@RequestBody Map<String,Object> in){Set<UUID> off=parseIds(in.get("disabledEdgeIds"));Set<UUID> known=new HashSet<>();baseWithFailures(uuid(id).toString()).edges().forEach(e->known.add(e.id()));if(!known.containsAll(off))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"One or more connection IDs do not exist in this revision");long version=((Number)in.getOrDefault("version",-1)).longValue();int changed;try{changed=db.update("UPDATE active_simulations SET disabled_edge_ids_json=?,version=version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE id=UUID_TO_BIN(?) AND version=?",json.writeValueAsString(off),uuid(id).toString(),version);}catch(Exception e){throw new IllegalStateException(e);}if(changed==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Scenario version is stale. Refresh and retry.");return ok(scenario(id));}
  @PostMapping("/simulations/{id}/restore") @Transactional public Map<String,Object> restoreScenario(@PathVariable String id,@RequestBody(required=false) Map<String,Object> in){Set<UUID> off=disabled(uuid(id).toString());Set<UUID> restore=parseIds(in==null?null:in.get("edgeIds"));Set<UUID> known=new HashSet<>();baseWithFailures(uuid(id).toString()).edges().forEach(e->known.add(e.id()));if(!known.containsAll(restore))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"One or more connection IDs do not exist in this revision");if(restore.isEmpty())off.clear();else off.removeAll(restore);long version=db.queryForObject("SELECT version FROM active_simulations WHERE id=UUID_TO_BIN(?)",Long.class,id);try{db.update("UPDATE active_simulations SET disabled_edge_ids_json=?,version=version+1 WHERE id=UUID_TO_BIN(?) AND version=?",json.writeValueAsString(off),id,version);}catch(Exception e){throw new IllegalStateException(e);}return ok(scenario(id));}
  @PostMapping("/simulations/{id}/reset") @Transactional public Map<String,Object> resetScenario(@PathVariable String id){return restoreScenario(id,Map.of("edgeIds",List.of()));}
  @PostMapping("/simulations/{id}/save") @Transactional public ResponseEntity<?> saveScenario(@PathVariable String id,@RequestBody Map<String,String> in){String name=in.get("name");if(name==null||name.isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"A scenario name is required");var r=scenario(id);Set<UUID> off=disabled(id);UUID history=UUID.randomUUID();try{db.update("INSERT INTO simulation_records(id,revision_id,disabled_edge_ids_json,result_json,name,notes,result_schema_version) SELECT UUID_TO_BIN(?),id,CAST(? AS JSON),CAST(? AS JSON),?,?,1 FROM network_revisions WHERE revision_number=?",history.toString(),json.writeValueAsString(off),json.writeValueAsString(r),name,in.get("notes"),r.get("baselineRevision"));}catch(Exception e){throw new IllegalStateException(e);}return ResponseEntity.status(201).body(ok(Map.of("id",history,"name",name,"result",r)));}
  @GetMapping("/history/simulations") public Map<String,Object> simulationHistory(){var rows=db.query("SELECT BIN_TO_UUID(id) id,name,created_at,CAST(result_json AS CHAR) result FROM simulation_records ORDER BY created_at DESC",(r,i)->{try{return Map.of("id",r.getString("id"),"name",r.getString("name"),"createdAt",r.getTimestamp("created_at").toInstant().toString(),"result",json.readTree(r.getString("result")));}catch(Exception e){throw new IllegalStateException(e);}});return ok(rows);}
}
